function bgApply(M,l,k){const b=BG[k];if(!b)return;l.bg=k;if(b.mon)S.money=(S.money||0)+b.mon;if(b.debt)l.debt+=b.debt;if(b.fit)l.fit=cl(l.fit+b.fit,0,100);if(b.st)l.st=cl(l.st+b.st,0,100);if(b.sk)l.sk=cl(l.sk+b.sk,0,100);if(b.eng)l.eng=cl(l.eng+b.eng,0,100);if(b.adapt)mwFx({adapt:b.adapt});if(b.fl)for(const x in b.fl)l.fl[x]=b.fl[x];if(b.tr&&!l.tr.includes(b.tr)&&l.tr.length<3)l.tr.push(b.tr)}
window.mwBgPick=function(){const M=S&&S.mw;if(!M||!lOn(M)||Ls(M).bg)return;modal(`<h3>🧬 ครอบครัวคุณเป็นแบบไหน</h3><p class="tag2">พื้นเพกำหนดเงินตั้งต้น ทักษะ ความเครียด และนิสัยประจำตัวที่ติดมาด้วย</p><div class="bgG">${Object.entries(BG).map(([k,b])=>`<button class="bgC" onclick="bgSet('${k}')"><span class="bgI">${b.ic}</span><b>${b.n}</b><small>${b.d}</small></button>`).join('')}<button class="bgC" onclick="bgSet('')"><span class="bgI">🎲</span><b>ปล่อยให้ชะตาเลือก</b><small>สุ่มหนึ่งแบบ และอาจได้นิสัยพิเศษ</small></button></div>`,'mbg')};
window.bgSet=function(k){const M=S&&S.mw;if(!M||!lOn(M))return;const l=Ls(M);if(l.bg)return;if(!BG[k])k=ch(Object.keys(BG));closeM();bgApply(M,l,k);const b=BG[k];log(`${b.ic} คุณเติบโตมาใน<b>${b.n}</b> — ${b.d}`+(l.tr.length?` · นิสัยประจำตัว: <b>${l.tr.join(' · ')}</b>`:''),'epic',true);try{render();saveGame()}catch(e){}};
