const lChips=(M,l)=>{const P=pvOf(M),bg=l.bg&&BG[l.bg];return`<div class="lchips"><span class="lchip">📍 ${P.n}</span>${bg?`<span class="lchip">${bg.ic} ${bg.n}</span>`:''}${(l.tr||[]).map(x=>`<span class="lchip" title="${esc(TRD[x]||'')}">${x}</span>`).join('')}${(l.ach||[]).length?`<span class="lchip ach">🏆 ${l.ach.length}/${ACH.length}</span>`:''}</div>`+(l.sl?`<div class="tag2">📖 เรื่องราวในชีวิตกำลังดำเนินอยู่ (${{land:'ที่ดินของครอบครัว',kid:'ลูกวัยรุ่น',band:'ฝันเสียงดนตรี',shop:'ขยายร้าน'}[l.sl.id]||''})</div>`:'')};
