function bar(v,c){return`<div style="height:8px;border-radius:4px;background:rgba(128,128,128,.25);overflow:hidden"><div style="width:${cl(v,0,100)}%;height:100%;background:${c}"></div></div>`}
window.openLife=function(){const M=S&&S.mw;if(!M)return;if(!lOn(M))return toast('ระบบนี้เปิดเฉพาะชีวิตในไทยตอนนี้');const l=Ls(M),B=(f,t,d)=>`<button class="gbtn jobA" ${d?'disabled style="opacity:.5"':''} onclick="${f}">${t}</button>`;
 const inv=l.inv,tot=inv.f+inv.s+inv.c,cash=S.money||0,net=cash+tot+(mwAst(M).save||0)-l.debt-l.loan;
 const prog=l.prog?`<div class="tag2">กำลังเรียน: <b>${esc(LEDU[l.prog.id].n)}</b> · เหลือ ${l.prog.left} ปี</div>`:'';
 const progs=l.prog?'':Object.entries(LEDU).filter(([id,P])=>{if(id==='lic'&&l.fl.lic)return false;if(id==='trade'&&l.fl.cert)return false;if(id==='eng'&&l.eng>=60)return false;if(id==='code'&&l.sk>=40)return false;return(P.min<0||l.edu>=P.min)&&l.edu<=P.max&&(!P.give||P.give>l.edu)}).map(([id,P])=>`<div class="jobC"><div class="jobH">${P.ic} <b>${esc(P.n)}</b></div><div class="tag2">${P.d} · ${P.yrs} ปี · ค่าเรียน ${fmt(Math.round(P.cost*l.cpi))} บาท/ปี${P.loan?' · กู้ กยศ. ได้':''}</div>${B(`lifeAct('enroll','${id}')`,'ลงเรียน',false)}</div>`).join('');
 const ins=(k,n,ic)=>`<div class="jobC"><div class="jobH">${ic} <b>${n}</b> ${fmt(inv[k])} บาท</div><div class="tag2">${k==='f'?'ผันผวนน้อย ผลตอบแทนช้า':k==='s'?'ขึ้นลงปานกลาง':'ขึ้นลงรุนแรง ล้มทั้งกระดานก็ได้'}</div>${B(`lifeAct('inv','${k}',0.2)`,'ลง 20% ของเงินสด',cash<5000)}${B(`lifeAct('inv','${k}',0.5)`,'ลง 50%',cash<5000)}${inv[k]>0?B(`lifeAct('out','${k}')`,'ขายทั้งหมด'):''}</div>`;
 const w=Object.keys(LW).map(Number).filter(y=>y>2026&&y<=MW_Y0+M.y&&LW[y].nm).slice(-4).reverse().map(y=>`<div class="tag2">ปี ${y}: <b>${LW[y].nm}</b></div>`).join('')||'<div class="tag2">ยังไม่มีเหตุการณ์ใหญ่</div>';
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🧭 ชีวิตคุณ · อายุ ${S.age}</h3>${lChips(M,l)}
 <p class="tag2">ทรัพย์สินสุทธิประมาณ <b>${fmt(net)}</b> บาท (เงินสด ${fmt(cash)} · ลงทุน ${fmt(tot)} · หนี้ ${fmt(l.debt+l.loan)})</p>
 <div class="jobL"><div class="jobC"><div class="jobH">❤️ ร่างกาย / จิตใจ</div><div class="tag2">เครียด ${Math.round(l.st)}/100</div>${bar(l.st,'#d9534f')}<div class="tag2">สภาพร่างกาย ${Math.round(l.fit)}/100${l.fl.chronic?' · โรคเรื้อรัง':''}${l.fl.smoke?' · สูบบุหรี่':''}${l.fl.gamb?' · ติดพนัน':''}</div>${bar(l.fit,'#3aa76d')}
 ${B(`lifeAct('rest')`,'ลาพักผ่อน 9,000 บาท (เครียด −20)')}${B(`lifeAct('doc')`,'พบนักจิตวิทยา 8,000 บาท (เครียด −25)')}${l.fl.gym?B(`lifeAct('gym')`,'ยกเลิกฟิตเนส'):B(`lifeAct('gym')`,'สมัครฟิตเนส 9,000/ปี')}</div>
 <div class="jobC"><div class="jobH">🎓 การศึกษา</div><div class="tag2">วุฒิ: <b>${EDN[l.edu]}</b> · ทักษะเทค ${Math.round(l.sk)} · อังกฤษ ${Math.round(l.eng)}${l.fl.cert?' · ใบรับรองช่าง':''}${l.fl.lic?' · มีใบขับขี่':''}</div>${prog}</div>${progs}
 <div class="jobC"><div class="jobH">💼 อาชีพ</div><div class="tag2">${M.job?esc(mwJP(MW_JOBS[M.job.id],M)[0]):'ยังไม่มีงานประจำ'}${l.ss>=1?' · ประกันสังคม '+l.ss+' ปี':''}</div>${B('closeM();openJobs()','ดูประกาศงาน')}</div>
 <div class="jobC"><div class="jobH">📍 จังหวัด: <b>${pvOf(M).n}</b> · ภาค${pvOf(M).r}</div><div class="tag2">ค่าครองชีพ ×${pvOf(M).col} · ค่าแรง ×${pvOf(M).wage}${M.home&&M.home!==M.pv?' · บ้านเกิด '+PV[M.home].n:''}</div><div class="tag2">${pvOf(M).d}</div>${B('pvPick(1)','ย้ายจังหวัด')}</div>
 <div class="jobC"><div class="jobH">📜 สรุปชีวิต</div><div class="tag2">ลูก ${l.kids.length} คน</div>${B('openLifeSum()','ดูสรุป')}</div>
 <div class="jobC"><div class="jobH">💰 การเงิน</div><div class="tag2">ค่าครองชีพ ${fmt(mwYearCost(M).mon)} บาท/เดือน (เงินเฟ้อสะสม ×${l.cpi.toFixed(2)})${l.debt?` · หนี้ ${fmt(l.debt)} ดอก 16%/ปี`:''}${l.loan?` · กยศ. ${fmt(l.loan)}`:''}</div>${l.debt>0?B(`lifeAct('pay')`,'ใช้เงินสดปิดหนี้',cash<1000):''}</div>
 ${ins('f','กองทุนรวมดัชนี','📊')}${ins('s','หุ้น','📈')}${ins('c','คริปโต','🪙')}
 <div class="jobC"><div class="jobH">🌏 ข่าวใหญ่ที่ผ่านมา</div>${w}</div></div>`,'mlife')}
window.lifeAct=function(k,a,b){const M=S&&S.mw;if(!M)return;const l=Ls(M),cash=S.money||0;
 if(k==='enroll'){if(!lEnroll(M,l,a,0))toast('ลงเรียนไม่ได้');}
 else if(k==='inv'){const x=Math.round(cash*b);if(x<=0)return;S.money-=x;l.inv[a]+=x;toast('ลงทุน '+fmt(x)+' บาท')}
 else if(k==='out'){S.money=cash+l.inv[a];l.inv[a]=0;toast('ขายแล้ว')}
 else if(k==='pay'){const p=Math.min(l.debt,cash);S.money-=p;l.debt-=p;toast('ปิดหนี้ '+fmt(p)+' บาท')}
 else if(k==='rest'){if(cash<9000)return toast('เงินไม่พอ');S.money-=9000;l.st=cl(l.st-20,0,100);joy(3);toast('พักแล้ว')}
 else if(k==='doc'){if(cash<8000)return toast('เงินไม่พอ');S.money-=8000;l.st=cl(l.st-25,0,100);l.fl.dep=0;joy(4);toast('เข้าพบแล้ว')}
 else if(k==='gym'){l.fl.gym=l.fl.gym?0:1}
 try{saveGame()}catch(e){}openLife()};
{const _r=render;render=function(){const r=_r.apply(this,arguments);try{if(mwOn()&&lOn(S.mw)){const j=document.querySelector('#mwHud .mwJob .mwAstB');if(j&&!j.parentNode.querySelector('.mwLifeB'))j.insertAdjacentHTML('afterend',` <button class="gbtn mwJobB mwAstB mwLifeB" onclick="openLife()">🧭 ชีวิต</button>`)}}catch(e){}return r}}
